Set-Location -LiteralPath $PSScriptRoot
$msg = 'sms: no URL in SMS. Email carries the scheduling link. Campaign CO3YNIF - VERIFIED, LOW_VOLUME, the campaign these messages actually send under - is registered has_embedded_links false and has_embedded_phone false, read live from Twilio rather than inferred, and five controlled sends on one number inside 33 minutes agree exactly: the four carrying a booking URL were filtered 30007, the one without was delivered. New app/services/sms_content_policy.py is the single guarantee. Rewriting the five default templates is not enough on its own, because a URL can still arrive from an org custom template, a cadence touch message_template, an AI draft, or an advisor pasting one into the composer, so the policy sits where all of those converge. It marks a disallowed span and removes the CLAUSE that introduced it, so book a time here colon URL does not become a dangling fragment reaching a grieving family, and it guarantees the opt-out line appears exactly once - not one template previously carried one, while both registered samples do. compose_body is the function the composer previews with, so a pasted link is watched disappearing before Send rather than silently dropped. No booking token is minted for a message that cannot carry it, in send_sms, send_mms and cadence, since an issued and undelivered token is a dead row claiming a family got a link they never received. pipeline_service, review_request_cron, appointment_flow_service and appointment_reminder_cron all enforce it too so none becomes a back door. EMAIL IS DELIBERATELY UNTOUCHED and still mints and renders the booking link. Section 3 of the sweep, which asserted the old append behaviour, is rewritten to the new rule rather than deleted, keeping the invariant it existed to protect. No Twilio configuration, A2P registration, calendar or booking architecture changed.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
